def transform_tiles(tiles, allow_reflect=True):
    allori=[]
    for arr in tiles:
        variants=[]
        for refl in (range(2) if allow_reflect else range(1)):
            a=[row[:] for row in arr]
            if refl: a=[row[::-1] for row in a]
            for rot in range(4):
                if rot:
                    a=[list(row) for row in zip(*a[::-1])]
                cells=[(r,c,a[r][c]) for r in range(len(a)) for c in range(len(a[0])) if a[r][c]]
                minr=min(r for r,c,v in cells);maxr=max(r for r,c,v in cells);minc=min(c for r,c,v in cells);maxc=max(c for r,c,v in cells)
                cells=tuple(sorted((r-minr,c-minc,v) for r,c,v in cells))
                key=(maxr-minr+1,maxc-minc+1,cells)
                if not any(x[0]==key for x in variants): variants.append((key,(maxr-minr+1,maxc-minc+1),cells))
        allori.append([x[2:] for x in variants])
    return allori
