def solve_mosaic(H=10,W=22, allow_reflect=True, max_nodes=2000000, seam=True):
    N=H*W;orient=transform_tiles(base_tiles,allow_reflect);bycell=[[] for _ in range(N)];placements=[]
    for pi,ors in enumerate(orient):
      for (hh,ww),cells in ors:
       for r0 in range(H-hh+1):
        for c0 in range(W-ww+1):
         cc=tuple((r0+r)*W+c0+c for r,c,v in cells);vals=tuple(v for r,c,v in cells);mask=sum(1<<x for x in cc)
         p=(pi,mask,cc,vals);pid=len(placements);placements.append(p)
         for x in cc: bycell[x].append(pid)
    occ=[0]*N;own=[-1]*N;ans=[];nodes=0
    def dfs(mask,usedmask):
      nonlocal nodes
      nodes+=1
      if nodes>max_nodes:return False
      if mask==(1<<N)-1:return usedmask==(1<<len(base_tiles))-1
      missing=(~mask)&((1<<N)-1);cell=(missing&-missing).bit_length()-1
      cand=[]
      for pid in bycell[cell]:
        pi,pm,cc,vals=placements[pid]
        if usedmask>>pi&1 or pm&mask: continue
        if seam:
          ok=True
          for x,v in zip(cc,vals):
            r,c=divmod(x,W)
            for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
             if 0<=nr<H and 0<=nc<W:
              y=nr*W+nc
              if own[y]>=0 and own[y]!=pi and occ[y]!=v:ok=False;break
            if not ok:break
          if not ok:continue
        cand.append(pid)
      cand.sort(key=lambda p:-len(placements[p][2]))
      for pid in cand:
        pi,pm,cc,vals=placements[pid]
        for x,v in zip(cc,vals):occ[x]=v;own[x]=pi
        if dfs(mask|pm,usedmask|(1<<pi)):
          ans.append((pi,tuple(cc),tuple(vals)))
          return True
        for x in cc:occ[x]=0;own[x]=-1
        if nodes>max_nodes:return False
      return False
    found=dfs(0,0)
    return found,nodes,ans,own,occ,placements
